namespace V15Voice {public partial class MainForm {
 Panel quickRepairPanel;Label quickTitle=new Label(),quickMetrics=new Label();TextBox quickOriginal=new TextBox(),quickProposed=new TextBox();AiRepairSession quickSession;int quickCue;bool quickEditing;AiAttempt quickDisplayed;readonly ToolTip quickHelp=new ToolTip{AutoPopDelay=20000};
 void BuildQuickPanel(){var left=(TableLayoutPanel)grid.Parent;left.RowCount=6;left.RowStyles.Add(new RowStyle(SizeType.Absolute,0));quickRepairPanel=new Panel{Dock=DockStyle.Fill,Visible=false,Padding=new Padding(4),BackColor=Color.FromArgb(238,246,251)};left.Controls.Add(quickRepairPanel,0,5);extraControls.Add(quickRepairPanel);left.SizeChanged+=(s,e)=>{if(quickRepairPanel.Visible)LayoutQuickRepair();};
  var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=5};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));foreach(int h in new[]{32,104,22,0,80})layout.RowStyles.Add(new RowStyle(h==0?SizeType.Percent:SizeType.Absolute,h==0?100:h));quickRepairPanel.Controls.Add(layout);
  var heading=new Panel{Dock=DockStyle.Fill,Margin=new Padding(0)};quickTitle.Dock=DockStyle.Fill;quickTitle.Font=new Font("Segoe UI",10,FontStyle.Bold);heading.Controls.Add(quickTitle);var close=new Button{Text="Danh sách",Dock=DockStyle.Right,Width=90};close.Click+=(s,e)=>CloseQuickRepair();heading.Controls.Add(close);layout.Controls.Add(heading,0,0);layout.SetColumnSpan(heading,2);quickMetrics.Dock=DockStyle.Fill;layout.Controls.Add(quickMetrics,0,1);layout.SetColumnSpan(quickMetrics,2);
  layout.Controls.Add(new Label{Text="LỜI GỐC",Dock=DockStyle.Fill},0,2);layout.Controls.Add(new Label{Text="LỜI ĐỀ XUẤT / TỰ CHỈNH",Dock=DockStyle.Fill},1,2);
  foreach(var t in new[]{quickOriginal,quickProposed}){t.Multiline=true;t.ReadOnly=true;t.ScrollBars=ScrollBars.Vertical;t.Dock=DockStyle.Fill;t.Font=new Font("Segoe UI",10);t.BackColor=Color.White;}layout.Controls.Add(quickOriginal,0,3);layout.Controls.Add(quickProposed,1,3);
  var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true,AutoScroll=true};layout.Controls.Add(buttons,0,4);layout.SetColumnSpan(buttons,2);
  Action<string,Func<Task>> add=(title,action)=>{var button=new Button{Text=title,AutoSize=true,MinimumSize=new Size(100,32)};button.Click+=async(s,e)=>{try{await action();}catch(Exception ex){status.Text=ex.InnerException==null?ex.Message:ex.InnerException.Message;}};buttons.Controls.Add(button);};
  add("AI SỬA KHÁC",async()=>{if(quickSession==null||busy)return;ValidateQuickSettings();var s=CaptureSettings();if(!LocalAi.Ready(root)&&MessageBox.Show(this,"Cài gói AI khoảng 2,5 GB một lần rồi sửa offline?","Cài AI",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;quickEditing=false;quickDisplayed=null;await RunInlineAi(quickSession,quickCue,new LocalAi(root,s.Device),AiFactory(s));});
  add("TỰ SỬA",()=>{quickEditing=true;quickProposed.ReadOnly=false;quickProposed.Focus();status.Text="Sửa lời, giữ các nhãn #số câu. CHẤP NHẬN sẽ đo TTS trước khi áp dụng.";return Task.FromResult(0);});
  add("ĐO LẠI",async()=>{if(quickSession==null||busy)return;await MeasureQuickManual();});
  add("NGHE THỬ",async()=>{if(quickSession==null||busy)return;if(quickEditing&&!await MeasureQuickManual())return;var row=InlineAiRepair.At(quickSession,quickCue);var words=QuickWords();var a=row.Attempts.LastOrDefault(x=>!x.Rejected&&x.Cues.Select(c=>c.Text).SequenceEqual(words.Select(c=>c.Text)));var m=a==null?row.Original:a.Measurement;if(m==null||!m.Valid){status.Text="Chưa có audio đo hợp lệ. Bấm AI SỬA KHÁC hoặc tự chỉnh để đo.";return;}Play(m.Audio);});
  add("CHẤP NHẬN",async()=>{if(quickSession==null||busy)return;ValidateQuickSettings();if(quickEditing&&!await MeasureQuickManual())return;var row=InlineAiRepair.At(quickSession,quickCue);var words=QuickWords();var a=row.Attempts.LastOrDefault(x=>x.Cues.Select(c=>c.Text).SequenceEqual(words.Select(c=>c.Text))&&RepairPolicy.Acceptable(x));if(a==null){status.Text="Không áp dụng: bản đang xem chưa được đo đạt hoặc đã bị chặn ngữ nghĩa.";return;}a.HumanApproved=true;row.Accepted=a.Number;InlineAiApplied(quickSession,quickCue);quickEditing=false;RefreshQuickRepair();status.Text="Đã chấp nhận lời đã đo đạt. Bấm TIẾP TỤC RENDER.";});
  add("TIẾP TỤC RENDER",async()=>{if(busy)return;if(quickEditing){status.Text="Chấp nhận và đo lời vừa chỉnh trước khi tiếp tục.";return;}CloseQuickRepair();await Export();});
  add("HOÀN TÁC",()=>{if(quickSession==null||busy)return Task.FromResult(0);var row=InlineAiRepair.At(quickSession,quickCue);row.Accepted=0;row.FinalVerified=false;InlineAiApplied(quickSession,quickCue);quickEditing=false;RefreshQuickRepair();return Task.FromResult(0);});
 }
 void ValidateQuickSettings(){if(quickSession==null)throw new Exception("Chọn câu lỗi trước.");quickSession.Validate();var s=CaptureSettings();if(!InlineAiRepair.Matches(quickSession,cues)||quickSession.Fingerprint!=AiVoiceFingerprint(s,AiFactory(s))||!AiRepairSession.SameSettings(quickSession.Settings,s.Xml().ToString()))throw new Exception("Kịch bản hoặc giọng đã đổi. Đóng khung sửa và bấm SỬA NGAY lại để đo đúng giọng.");}
 void LayoutQuickRepair(){var left=(TableLayoutPanel)grid.Parent;bool compact=left.ClientSize.Width<800;wavePanel.Visible=false;left.RowStyles[4].Height=0;grid.Visible=!compact;left.RowStyles[3].SizeType=compact?SizeType.Absolute:SizeType.Percent;left.RowStyles[3].Height=compact?0:100;left.RowStyles[5].SizeType=SizeType.Absolute;left.RowStyles[5].Height=compact?Math.Max(280,left.ClientSize.Height-left.RowStyles[0].Height-left.RowStyles[1].Height-left.RowStyles[2].Height-4):340;quickRepairPanel.PerformLayout();foreach(Control child in quickRepairPanel.Controls)child.PerformLayout();}
 void CloseQuickRepair(){if(quickRepairPanel==null)return;quickRepairPanel.Visible=false;var left=(TableLayoutPanel)grid.Parent;left.RowStyles[5].SizeType=SizeType.Absolute;left.RowStyles[5].Height=0;left.RowStyles[3].SizeType=SizeType.Percent;left.RowStyles[3].Height=100;grid.Visible=true;wavePanel.Visible=true;left.RowStyles[4].Height=56;}
 void ShowQuickRepair(AiRepairSession session,int id){if(quickRepairPanel==null)return;quickSession=session;quickCue=id;quickEditing=false;quickDisplayed=null;quickProposed.ReadOnly=true;quickRepairPanel.Visible=true;LayoutQuickRepair();RefreshQuickRepair();}
 void RefreshQuickRepair(){if(quickSession==null||quickRepairPanel==null||!quickRepairPanel.Visible)return;var row=InlineAiRepair.At(quickSession,quickCue);if(row==null)return;quickTitle.Text="SỬA NGAY · cue "+String.Join(",",row.Stage.Cues.Select(c=>c.Id))+" · "+Scripts.Stamp(row.Stage.Start)+" → "+Scripts.Stamp(row.Stage.End);quickOriginal.Text=String.Join("\r\n\r\n",row.Stage.Cues.Select(c=>"#"+c.Id+": "+c.Text));var a=quickDisplayed!=null&&row.Attempts.Contains(quickDisplayed)?quickDisplayed:row.Chosen??row.Best??row.Attempts.LastOrDefault();var m=a==null||a.Measurement==null?row.CurrentMeasure:a.Measurement;if(!quickEditing)quickProposed.Text=String.Join("\r\n\r\n",(a==null||a.Cues.Count==0?row.CurrentWords:a.Cues).Select(c=>"#"+c.Id+": "+c.Text));quickMetrics.Text="Đích "+row.Stage.Budget.ToString("0.000")+"s · "+(m==null?"chưa đo":m.Error.Length>0?m.Kind+": "+m.Error:"TTS + nghỉ "+m.Natural.ToString("0.000")+"s → "+m.After.ToString("0.000")+"s · dư (+)/thiếu (-) "+m.Delta.ToString("+0.000;-0.000;0")+"s")+"\r\n"+row.Status+" · AI "+row.AutoAttempts+" / 3"+(a==null?"":a.SemanticSafe?" · ngữ nghĩa: từ chuẩn hóa giữ nguyên":" · cần người dùng duyệt ý nghĩa")+"\r\n"+(a==null?row.Error:(a.Rejected?"BỊ LOẠI · ":"")+(a.Measurement==null?"chưa đo đề xuất; số đo của lời đang dùng · ":"")+a.Code+" · "+a.Strategy+" · "+a.Error);quickHelp.SetToolTip(quickMetrics,quickMetrics.Text+(a==null?"":"\r\n"+a.SemanticReason));}
 List<Cue> QuickWords(){var row=InlineAiRepair.At(quickSession,quickCue);var matches=Regex.Matches(quickProposed.Text,@"(?ms)^#(\d+):\s*(.*?)(?=^#\d+:|\z)");if(matches.Count!=row.Stage.Cues.Count)throw new Exception("Giữ đúng các nhãn #số câu; không thêm/xóa cue.");var words=VoiceRenderReport.Snapshot(row.Stage.Cues);for(int i=0;i<words.Count;i++){if(Int32.Parse(matches[i].Groups[1].Value)!=words[i].Id)throw new Exception("Không đổi thứ tự số câu.");words[i].Text=matches[i].Groups[2].Value.Trim();}return words;}
 async Task<bool> MeasureQuickManual(){ValidateQuickSettings();var p=quickSession;int id=quickCue;var words=QuickWords();var settings=CaptureSettings();var factory=AiFactory(settings);inlineAiCancelled=false;SetBusy(true);try{await Task.Run(()=>{AiTimeline.Run(p,new LocalAi(root,settings.Device),role=>{inlineAiEngine=factory(role);return inlineAiEngine;},()=>inlineAiCancelled,(n,m)=>{},false,false,id);AiTimeline.MeasureManual(p,InlineAiRepair.At(p,id),words,role=>{inlineAiEngine=factory(role);return inlineAiEngine;},()=>inlineAiCancelled);});quickEditing=false;quickProposed.ReadOnly=true;var a=InlineAiRepair.At(p,id).Attempts.Last();quickDisplayed=a;if(!RepairPolicy.Acceptable(a)){status.Text="Lời tự chỉnh chưa vừa khung hoặc engine lỗi; chưa áp dụng.";return false;}return true;}finally{inlineAiEngine=null;SetBusy(false);RefreshQuickRepair();}}
 void AdoptPendingRepair(AiRepairSession p){inlineAiSession=p;inlineAiFingerprint=p.Fingerprint;cues=p.Effective();pendingAi=p;pendingAiSnapshot=AiRepairSession.SnapshotHash(cues);lastVoiceReport=p.Report;foreach(var row in p.Rows)foreach(var c in cues.Where(c=>row.Stage.Cues.Any(w=>w.Id==c.Id)))c.Status=RepairRecovery.RowDetail(row);if(editingJob!=null){editingJob.Cues=cues;editingJob.AiReport=p.Report;editingJob.AiSnapshot=pendingAiSnapshot;}Populate();var first=p.Rows.FirstOrDefault(r=>r.CurrentMeasure==null||r.CurrentMeasure.NeedsRepair||r.CurrentMeasure.Error.Length>0);if(first!=null&&!IsDisposed)BeginInvoke((Action)(()=>{if(!busy)ShowQuickRepair(p,first.Stage.Cues[0].Id);}));}
